# -*- coding: utf-8 -*-
from pathlib import Path
import json, shutil, html
root=Path(__file__).resolve().parent.parent
research=root.parent/'research'
data=json.loads((research/'sources.json').read_text())
labels={'design_render':'方案效果图','as_built_photo':'建成实景','construction_photo':'施工实拍','engineering_diagram':'工程图','interior_photo':'内部实拍','original_drawing':'原始工程图','diagram':'工程示意','detail_crop':'局部参考'}
cards=[]
for a in data['assets']:
    if not a.get('independent_visual'):continue
    p=Path(a['local_path']); name=p.name
    shutil.copy2(p,root/'assets/references'/name)
    title=html.escape(a['title']);url=html.escape(a['page_url'],quote=True)
    kind=labels.get(a['kind'],a['kind'])
    cards.append(f'''<article><a href="{url}" target="_blank" rel="noopener"><img loading="lazy" src="./assets/references/{name}" alt="{title}"></a><div class="caption"><small>{html.escape(kind)} · {a['evidence_level']} 类形态依据</small><h2>{title}</h2><p>{html.escape(a['observation'])}</p><a href="{url}" target="_blank" rel="noopener">查看原始来源 ↗</a></div></article>''')
css='''*{box-sizing:border-box}body{margin:0;background:#f3f5f1;color:#29434f;font-family:Arial,"PingFang SC",sans-serif}header{display:flex;justify-content:space-between;border-bottom:1px solid #c7d3d4;padding:28px 5vw;font-size:12px;letter-spacing:2px}a{color:#447d92;text-decoration:none}main{padding:60px 5vw}h1{font-family:"Songti SC",serif;font-weight:400;font-size:44px;letter-spacing:4px;margin:0 0 20px}.intro{max-width:750px;font-size:13px;line-height:2;color:#74878f}.facts{margin:35px 0 45px;padding:25px;border:1px solid #c4d4d8;max-width:1000px;background:#e9efed}.facts p{font-size:12px;line-height:2;margin:6px 0}.facts strong{font-weight:500;color:#325969}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}article{border:1px solid #ced9d8;background:#fbfcf8}img{width:100%;height:230px;object-fit:cover;display:block}.caption{padding:23px}small{font-size:9px;letter-spacing:1px;color:#7798a4}h2{font-size:17px;font-weight:500;margin:12px 0}article p{font-size:11px;line-height:1.9;color:#7b8d94;min-height:60px}article a{font-size:10px}footer{border-top:1px solid #c7d3d4;margin-top:60px;padding-top:25px;color:#85969b;font-size:11px;line-height:2}.docs{display:flex;gap:25px;flex-wrap:wrap;margin:30px 0;font-size:12px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){header{font-size:9px}.grid{grid-template-columns:1fr}main{padding-top:35px}h1{font-size:32px}img{height:240px}.caption p{min-height:0}}'''
page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>伊蒂哈德 · 参考档案</title><style>{css}</style></head><body><header><b>ETIHAD / REFERENCE ARCHIVE</b><a href="./index.html">← 返回三维球场</a></header><main><small>RESEARCH EDITION 02 / 2026.10.29</small><h1>用证据，搭建一座球场。</h1><p class="intro">22 张独立参考画面，覆盖原球场、2015 南看台、2026 新北看台和北侧配套。实景、施工照片与早期方案分别标识。选取的内部影像留作后续研究，不代表当前已经复原相应内部空间。图片版权属于原摄影师、俱乐部及设计机构，点击图片可查阅来源。</p><div class="facts"><p><strong>A / 已核验尺寸：</strong>草坪白线间 105 × 68 米；场地较原地面下挖约 6 米。</p><p><strong>B / 有影像及工程依据的形态：</strong>原结构 12 桅杆（其中 8 根由交通塔支承）、8 螺旋交通塔、76 前拉索及四股张力环索；2026 北看台扩大为 59 排的连续上层。新看台容量口径为 61,000+。</p><p><strong>C / 尚待图纸校准：</strong>外轮廓、酒店与翼楼长宽高、逐席坐标、照明灯位和道路定位。原三层通用环廊标高 0.82 / 9 / 20.1 米为暂定。另已核验北看台批准图纸中的八个 FFL 标高，提供独立控制框，轮廓与主体仍待校准。模型为米制初步重建，不是测绘认证的全场 1∶1 模型。2023 方案不等同于 2026 所有设施的竣工状态。</p></div><div class="docs"><a href="https://www.arup.com/globalassets/downloads/arup-journal/the-arup-journal-2003-issue-1.pdf" target="_blank" rel="noopener">Arup 原始工程图文 ↗</a><a href="https://beta.mancity.com/news/club/stadium-relabelling-announcement-63886266" target="_blank" rel="noopener">曼城 · 新上层 59 排 ↗</a><a href="https://www.mancity.com/news/mens/manchester-city-etihad-stand-renaming-63915045" target="_blank" rel="noopener">曼城 · 2026 北看台 ↗</a></div><div class="docs"><a href="https://www.kalzip.com/en/references/etihad-stadium-manchester/" target="_blank" rel="noopener">Kalzip · 自然铝屋面与65/400板型 ↗</a></div><div class="docs"><a href="./models/Etihad-2026-editable-models.zip">↓ 下载米制建筑母模型 · GLB 压缩包</a></div><div class="docs"><a href="https://arcusbe.manchester.gov.uk/pr/s/detail/a1DSl000007GPxsMAG?c__r=Arcus_BE_Public_Register" target="_blank" rel="noopener">市政 · 2025 修订图纸与批准记录 ↗</a></div><div class="grid">{''.join(cards)}</div><footer>母模型范围：主场本体与已有北侧附属建筑。18 组建筑系统、三层可编辑环廊楼板与柱网、屋架及灯具支架；未扩大外围场地。<br>结构爆炸图为展示分层示意；当前场景不含可开闭屋顶，也不声称复原了未建模的后台室内空间。<br>独立建筑研究作品，与曼城俱乐部及设计单位无隶属关系。</footer></main></body></html>'''
(root/'research.html').write_text(page)
print(f'Built research archive with {len(cards)} independent images.')

shutil.copytree(root/'assets',root/'dist/assets',dirs_exist_ok=True)
